import{_ as r,o as t,c as a,ae as o}from"./chunks/framework.Dn6zxbF8.js";const g=JSON.parse('{"title":"Platforms and frameworks: exposure and health endpoints","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1008684393/references/platforms.md","filePath":"adrs/1008684393/references/platforms.md"}'),n={name:"adrs/1008684393/references/platforms.md"};function s(l,e,i,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="platforms-and-frameworks-exposure-and-health-endpoints" tabindex="-1">Platforms and frameworks: exposure and health endpoints <a class="header-anchor" href="#platforms-and-frameworks-exposure-and-health-endpoints" aria-label="Permalink to &quot;Platforms and frameworks: exposure and health endpoints&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-11.</p><h2 id="exposure" tabindex="-1">Exposure <a class="header-anchor" href="#exposure" aria-label="Permalink to &quot;Exposure&quot;">​</a></h2><p>Platforms aimed at application developers call the inside level <strong>private</strong>:</p><ul><li>Render: a <strong>Private Service</strong> has no public URL and is meant &quot;for internal APIs and microservices that should only be accessible to your own infrastructure&quot; (<a href="https://render.com/docs/private-services" target="_blank" rel="noreferrer">Private services</a>).</li><li>Railway: <strong>Private Networking</strong> gives every service a <code>*.railway.internal</code> name, apart from <strong>Public Networking</strong> (<a href="https://docs.railway.com/reference/private-networking" target="_blank" rel="noreferrer">Private networking</a>).</li><li>Fly.io: <strong>private networking</strong> over 6PN addresses and <code>&lt;app&gt;.internal</code> names (<a href="https://fly.io/docs/networking/private-networking/" target="_blank" rel="noreferrer">Private networking</a>).</li><li>Knative: the <code>networking.knative.dev/visibility: cluster-local</code> label keeps a service off the external gateway (<a href="https://knative.dev/docs/serving/services/private-services/" target="_blank" rel="noreferrer">Private services</a>).</li><li>DigitalOcean App Platform: <code>internal_ports</code> without an <code>http_port</code> keeps a component on the private network (<a href="https://docs.digitalocean.com/products/app-platform/how-to/manage-internal-routing/" target="_blank" rel="noreferrer">Internal routing</a>).</li></ul><p>Heroku is the exception, with <strong>Internal Routing</strong> for apps in Private Spaces (<a href="https://devcenter.heroku.com/articles/internal-routing" target="_blank" rel="noreferrer">Internal routing</a>). OpenShift sets an ingress controller&#39;s load balancer <code>scope</code> to <code>External</code> or <code>Internal</code> (<a href="https://github.com/openshift/api/blob/master/operator/v1/types_ingresscontroller.go" target="_blank" rel="noreferrer">IngressController API</a>).</p><p>Cloudflare puts staff tools behind Access, enforcing identity at its edge, and Tunnel, which connects the origin outward so it opens no inbound port (<a href="https://developers.cloudflare.com/cloudflare-one/setup/secure-private-apps/private-web-app" target="_blank" rel="noreferrer">Secure private web apps</a>).</p><h2 id="health-endpoints" tabindex="-1">Health endpoints <a class="header-anchor" href="#health-endpoints" aria-label="Permalink to &quot;Health endpoints&quot;">​</a></h2><ul><li>GitLab serves <code>/-/health</code>, <code>/-/readiness</code> and <code>/-/liveness</code> on its main port (<a href="https://docs.gitlab.com/administration/monitoring/health_check/" target="_blank" rel="noreferrer">Health check</a>).</li><li>Prometheus serves <code>/-/healthy</code> and <code>/-/ready</code>, plus <code>/-/reload</code> and <code>/-/quit</code> once <code>--web.enable-lifecycle</code> is set (<a href="https://prometheus.io/docs/prometheus/latest/management_api/" target="_blank" rel="noreferrer">Management API</a>).</li><li>Spring Boot Actuator serves <code>/actuator/health/liveness</code> and <code>/actuator/health/readiness</code>, optionally on a separate management port (<a href="https://docs.spring.io/spring-boot/reference/actuator/endpoints.html#actuator.endpoints.kubernetes-probes" target="_blank" rel="noreferrer">Kubernetes probes</a>).</li><li>Quarkus serves <code>/q/health/live</code>, <code>/q/health/ready</code> and <code>/q/health/started</code> (<a href="https://quarkus.io/guides/smallrye-health" target="_blank" rel="noreferrer">SmallRye Health</a>).</li></ul><p>GitLab and Prometheus both reserve <code>/-/</code> for operational endpoints, so they cannot collide with application routes.</p><h2 id="grpc-health-protocol" tabindex="-1">gRPC health protocol <a class="header-anchor" href="#grpc-health-protocol" aria-label="Permalink to &quot;gRPC health protocol&quot;">​</a></h2><p><code>grpc.health.v1.Health</code> defines <code>Check</code>, <code>Watch</code> and <code>List</code>. The empty service name means the health of the whole server; other names are matched exactly, and the protocol does not mandate a naming scheme (<a href="https://github.com/grpc/grpc/blob/master/doc/health-checking.md" target="_blank" rel="noreferrer">gRPC health checking</a>). <code>grpc-health-probe</code> checks it from the command line and predates the Kubernetes <code>grpc</code> probe (<a href="https://github.com/grpc-ecosystem/grpc-health-probe" target="_blank" rel="noreferrer">grpc-health-probe</a>).</p>',12)])])}const f=r(n,[["render",s]]);export{g as __pageData,f as default};
